/*
 * Multi-file project types for React + TypeScript generation.
 *
 * Milestone 3.1 introduces project-specific file structures generated by the AI.
 * Each project carries a manifest and an array of files with paths and contents.
 * This is layered on top of the existing Milestone 2 ProjectFiles (html/css/js)
 * which continues to be used for drafts/applied preview state.
 */

/** A single file in a generated project. */
export interface ProjectFile {
  /** Relative path within the project, e.g. "src/App.tsx" or "src/styles.css". */
  path: string;
  /** File content as UTF-8 text. */
  content: string;
}

/** Project metadata describing the generated React + TypeScript application. */
export interface ProjectManifest {
  /** kebab-case project name, e.g. "my-landing-page". */
  name: string;
  /** Semantic version string. */
  version: string;
  /** Entry point path, must exist in files, e.g. "src/main.tsx". */
  entry: string;
  /** Approved dependencies with exact versions. */
  dependencies: Record<string, string>;
  /** Framework identifier. */
  framework: "react-ts";
}

/** Complete AI generation result: manifest + source files. */
export interface ProjectResult {
  manifest: ProjectManifest;
  files: ProjectFile[];
}

/** Approved dependency versions for generated projects. */
export const APPROVED_DEPENDENCIES: Record<string, string> = {
  react: "19.0.0",
  "react-dom": "19.0.0",
  "react-dom/client": "19.0.0",
  "react/jsx-runtime": "19.0.0",
  gsap: "3.12.5",
  "gsap/ScrollTrigger": "3.12.5",
  "@gsap/react": "2.1.0",
} as const;

/** Set of approved bare import specifiers (exact or prefix-matched). */
export const APPROVED_IMPORTS = new Set([
  "react",
  "react-dom",
  "react-dom/client",
  "react/jsx-runtime",
  "gsap",
  "gsap/",
  "@gsap/react",
]);

/** Check whether an import specifier is approved for use in generated projects. */
export function isApprovedImport(specifier: string): boolean {
  if (APPROVED_IMPORTS.has(specifier)) return true;
  return [...APPROVED_IMPORTS].some((p) => p.endsWith("/") && specifier.startsWith(p));
}

/** Validate a project manifest. Returns error message or null. */
export function validateManifest(
  manifest: unknown,
): { ok: true; manifest: ProjectManifest } | { ok: false; error: string } {
  if (!manifest || typeof manifest !== "object" || Array.isArray(manifest)) {
    return { ok: false, error: "manifest must be an object" };
  }
  const m = manifest as Record<string, unknown>;
  if (typeof m.name !== "string" || m.name.length === 0) {
    return { ok: false, error: "manifest.name must be a non-empty string" };
  }
  if (typeof m.version !== "string" || m.version.length === 0) {
    return { ok: false, error: "manifest.version must be a non-empty string" };
  }
  if (typeof m.entry !== "string" || m.entry.length === 0) {
    return { ok: false, error: "manifest.entry must be a non-empty string" };
  }
  if (!m.entry.endsWith(".tsx") && !m.entry.endsWith(".ts")) {
    return { ok: false, error: "manifest.entry must be a .tsx or .ts file" };
  }
  if (
    typeof m.dependencies !== "object" ||
    Array.isArray(m.dependencies) ||
    m.dependencies === null
  ) {
    return { ok: false, error: "manifest.dependencies must be an object" };
  }
  if (m.framework !== "react-ts") {
    return { ok: false, error: "manifest.framework must be 'react-ts'" };
  }
  // All dependency keys must be approved
  for (const [key, value] of Object.entries(m.dependencies)) {
    if (typeof value !== "string") {
      return { ok: false, error: `dependency ${key} version must be a string` };
    }
    // Check exact or prefix match against approved imports
    const approved = [...APPROVED_IMPORTS].some(
      (p) => p === key || (p.endsWith("/") && key.startsWith(p)),
    );
    if (!approved) {
      return { ok: false, error: `dependency ${key} is not approved` };
    }
  }
  return {
    ok: true,
    manifest: {
      name: m.name as string,
      version: m.version as string,
      entry: m.entry as string,
      dependencies: m.dependencies as Record<string, string>,
      framework: "react-ts",
    },
  };
}

/** Validate a project file entry. Returns error message or null. */
export function validateProjectFile(
  file: unknown,
): { ok: true; file: ProjectFile } | { ok: false; error: string } {
  if (!file || typeof file !== "object" || Array.isArray(file)) {
    return { ok: false, error: "file must be an object" };
  }
  const f = file as Record<string, unknown>;
  if (typeof f.path !== "string" || f.path.length === 0) {
    return { ok: false, error: "file.path must be a non-empty string" };
  }
  if (typeof f.content !== "string") {
    return { ok: false, error: `file.content for ${f.path} must be a string` };
  }
  // Prevent path traversal
  const normalized = f.path.replace(/\\/g, "/");
  if (normalized.startsWith("/") || normalized.includes("..")) {
    return { ok: false, error: `file.path ${f.path} contains traversal or absolute path` };
  }
  const segments = normalized.split("/");
  for (const seg of segments) {
    if (seg === ".." || seg === "." || seg.length === 0) {
      return { ok: false, error: `file.path ${f.path} has invalid segment` };
    }
  }
  if (segments.length > 8) {
    return { ok: false, error: `file.path ${f.path} is too deep (max 8 segments)` };
  }
  return { ok: true, file: { path: normalized, content: f.content as string } };
}

/** Validate a complete ProjectResult. */
export function validateProjectResult(
  result: unknown,
): { ok: true; result: ProjectResult } | { ok: false; error: string } {
  if (!result || typeof result !== "object" || Array.isArray(result)) {
    return { ok: false, error: "result must be an object" };
  }
  const r = result as Record<string, unknown>;
  const manifestCheck = validateManifest(r.manifest);
  if (!manifestCheck.ok) {
    return { ok: false, error: `manifest: ${manifestCheck.error}` };
  }
  if (!Array.isArray(r.files) || r.files.length === 0) {
    return { ok: false, error: "files must be a non-empty array" };
  }
  const files: ProjectFile[] = [];
  const seenPaths = new Set<string>();
  for (const file of r.files) {
    const fileCheck = validateProjectFile(file);
    if (!fileCheck.ok) {
      return { ok: false, error: `file: ${fileCheck.error}` };
    }
    if (seenPaths.has(fileCheck.file.path)) {
      return { ok: false, error: `duplicate file path: ${fileCheck.file.path}` };
    }
    seenPaths.add(fileCheck.file.path);
    files.push(fileCheck.file);
  }
  // Entry point must exist in files
  const entryExists = files.some((f) => f.path === manifestCheck.manifest.entry);
  if (!entryExists) {
    return {
      ok: false,
      error: `manifest.entry ${manifestCheck.manifest.entry} not found in files`,
    };
  }
  return {
    ok: true,
    result: { manifest: manifestCheck.manifest, files },
  };
}